"""Authored synthetic packets; expected fields are held outside the evidence passed to the extractor."""
from qualify.conclusion_packets import cases as pilot

def packet(name,split,q,docs,kind,subject,expected=None):
    # For a decidable case specify the two evidence document names as well as both quantities.
    gold=None
    if expected:
        threshold,op,actual,verdict,rule,obs=expected
        gold=dict(kind=kind, subject=subject.casefold(), metric='unrestricted_cash' if kind=='cash' else 'uptime', period='quarter_end' if kind=='cash' else 'full_month', unit='USD_million' if kind=='cash' else 'percent',threshold=str(threshold),op=op,actual=str(actual),verdict=verdict,rule_file=rule+'.pdf',actual_file=obs+'.pdf')
    return dict(case=name,split=split,q=q,documents=[dict(id=str(i),name=n+'.pdf',pages=[t]) for i,(n,t) in enumerate(docs)],gold=gold)

def cases():
    out=[]
    for c in pilot():
        k=c['case']
        if k not in ('liquidity','uptime'):continue
        args=('cash','West',(50,'ge',52,'met','Covenant','Signed')) if k=='liquidity' else ('uptime','Service',(99,'gt',99,'missed','Policy','Ledger'))
        out.append(packet(k,'design',c['question'],[(d['name'][:-4],d['pages'][0]) for d in c['documents']],*args))
    def cash(name,ss,rule,obs,extra,gold,split='controlled'):
        return packet(name,split,f'Did {ss} meet its quarter-end unrestricted cash floor?', [('Covenant',rule),('Ledger',obs),('Flash',extra)],'cash',ss,gold)
    def uptime(name,ss,rule,obs,extra,gold,split='controlled'):
        return packet(name,split,f'Did {ss} meet its full-month uptime commitment?', [('Policy',rule),('Ledger',obs),('Dashboard',extra)],'uptime',ss,gold)
    for subject,k,x,word,rel,ans in [('Heron',32,32,'at least','ge','met'),('Jade',48,48,'strictly above','gt','missed'),('Cedar',25,24,'at least','ge','missed'),('Pearl',79,81,'strictly above','gt','met')]:
        out.append(cash(subject,subject,f'{subject} must hold {word} {k} million dollars of unrestricted cash at quarter end.',f'The signed quarter-end ledger records {x} million dollars of unrestricted cash for {subject}.',f'The preliminary quarter-end total cash figure for {subject} was {k+6} million dollars.',(k,rel,x,ans,'Covenant','Ledger')))
    for subject,k,x,word,rel,ans in [('Ember','99.5','99.5','strictly above','gt','missed'),('Indigo','98.4','98.4','at least','ge','met'),('Larch','97.5','98','strictly above','gt','met'),('Ash','99','98.9','at least','ge','missed')]:
        out.append(uptime(subject,subject,f'{subject} requires {word} {k} percent uptime for the entire month.',f'The signed full-month uptime ledger for {subject} shows {x} percent.',f'The dashboard for {subject} showed 99.9 percent uptime for the first week only.',(k,rel,x,ans,'Policy','Ledger')))
    cr='Mint must hold at least 60 million dollars of unrestricted cash at quarter end.'; co='The signed quarter-end ledger records 64 million dollars of unrestricted cash for Mint.'; ca='The preliminary quarter-end total cash figure for Mint was 72 million dollars.'; ur='Flint requires strictly above 99 percent uptime for the entire month.';uo='The signed full-month uptime ledger for Flint shows 99.2 percent.';uw='The dashboard for Flint showed 99.9 percent uptime for the first week only.'
    out += [cash('cash-conflict','Mint',cr,co,co.replace('64','58'),None),cash('cash-signed-correction','Mint',cr,'The signed quarter-end reconciliation supersedes the flash and records 57 million dollars of unrestricted cash for Mint.',co,(60,'ge',57,'missed','Covenant','Ledger')),cash('cash-total-only','Mint',cr,co.replace('unrestricted cash','total cash'),ca,None),cash('cash-other-issuer','Mint',cr,co.replace('Mint','Iris'),ca,None),cash('cash-new-period','Mint',cr,co.replace('quarter-end','prior-quarter'),ca,None),uptime('only-week','Flint',ur,uw,uw,None),uptime('different-service','Flint',ur,uo.replace('Flint','Granite'),uw,None),uptime('two-full-months','Flint',ur,uo,uo.replace('99.2','98.7'),None),uptime('withdrawn-observation','Flint',ur,uo,'The signed full-month uptime ledger for Flint was withdrawn without replacement.',None),cash('forecast-only','Mint',cr,'Mint expects to show 64 million dollars of unrestricted cash at quarter end.',ca,None)]
    # Separately worded development challenge. Some cases are deliberately outside any guaranteed grammar.
    out += [cash('paraphrase-cash','Reed','At quarter end, Reed needs no less than $40 million in unrestricted cash.','For Reed, the signed closing statement puts unrestricted cash at $43 million at quarter end.','Total cash for Reed at quarter end was $58 million, per the preliminary flash.',(40,'ge',43,'met','Covenant','Ledger'),'challenge'),cash('cash-table','Rush','Rush must hold at least 30 million dollars of unrestricted cash at quarter end.','Rush | quarter end | unrestricted cash | USD million | 29 | signed actual','The preliminary quarter-end total cash figure for Rush was 35 million dollars.',(30,'ge',29,'missed','Covenant','Ledger'),'challenge'),uptime('prose-window','Elm','For Elm, full-month uptime must exceed 99.5%.','Elm had a signed full-month uptime of 99.5%.','The dashboard for Elm showed 99.8 percent uptime for the first week only.',('99.5','gt','99.5','missed','Policy','Ledger'),'challenge'),uptime('period-in-footnote','Iris','Iris requires at least 98 percent uptime for the entire month.','Iris: 98.4% uptime (signed ledger; reporting window: the full month).','The dashboard for Iris showed 99.9 percent uptime for the first week only.',(98,'ge','98.4','met','Policy','Ledger'),'challenge'),cash('foreign-currency','Mint',cr,co.replace('dollars','euros'),ca,None,'challenge'),cash('withdrawal-after-correction','Mint',cr,'The signed quarter-end reconciliation supersedes the flash and records 64 million dollars of unrestricted cash for Mint. This reconciliation was subsequently withdrawn.',ca,None,'challenge'),cash('incomplete-reference','Mint',cr,'The signed quarter-end reconciliation supersedes the appendix and records 64 million dollars of unrestricted cash for Mint.',co.replace('64','58'),None,'challenge'),uptime('only-target','Flint',ur,'Flint is forecast to achieve 99.8 percent full-month uptime.',uw,None,'challenge'),uptime('another-month','Flint',ur,'The signed uptime ledger for Flint shows 99.2 percent for the previous month.',uw,None,'challenge'),cash('two-cash-definitions','Mint',cr,'The signed ledger records 64 million dollars of cash for Mint at quarter end; the unrestricted portion was not disclosed.',ca,None,'challenge')]
    return out
